/**
 * 白い熊 Stylus — the fork's preinstalled style library.
 *
 * A fresh install arrives with the reading setup already in place: a bg/fg matrix of ten global
 * styles that occupies popup positions 1-9 and 0, three typography globals, nine UI-affordance
 * globals, and the site-specific leftovers. Per-site tuning is then Stylus' own per-style
 * exclusions — popup, ☰, the "−" box on the domain row, or <Shift-1> from the keyboard.
 *
 * The styles themselves are generated by tools/make-default-styles.py into
 * ./fork-default-styles.json — edit the generator, never the JSON.
 */
import {deepCopy} from '@/js/util';
import {bgBusy} from './common';
import {prefsDB} from './db';
import {importMany, remove} from './style-manager';
import {styleMap} from './style-manager/util';
import DEFAULT_STYLES from './fork-default-styles.json';

/** prefsDB is a plain key/value store and mirrorStorage() only mirrors an explicit allowlist,
 * so keys of our own here are inert, stay local, and never reach the sync backends. */
const HASH_KEY = 'fork.defaultStylesHash';
/** Stamped on every style we install, so a later sync knows which ones are ours to touch. */
const MARK = '_forkDefault';

/** djb2 over the shipped JSON. Not a security hash — it only has to change when the library does. */
function hashOf(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (h * 33 ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36) + '.' + str.length.toString(36);
}

/**
 * Bring the installed library into line with the one this build ships. Hooked onto bgBusy, so it
 * is reconsidered at every startup.
 *
 * An earlier version of this seeded **once** and then refused to run again, gated on the style
 * database being non-empty. That protected a hand-tuned library, but it also meant every later
 * build shipped a corrected library that was silently discarded at startup — the styles on disk
 * stayed frozen at whatever the first install happened to write. Hence a sync rather than a seed.
 *
 * The rules of the sync:
 *
 * - It is gated on a hash of the shipped JSON, so an unchanged library costs one prefsDB read per
 *   startup and nothing else.
 * - Styles are matched **by name**. A match keeps everything 白い熊 tuned — the id, the on/off
 *   state, and above all the per-site `exclusions` and `inclusions`, which are the whole point of
 *   the library — and replaces only the CSS. Hand-edited CSS in one of these styles is therefore
 *   overwritten on the next library change; the generator is the source of truth.
 * - Styles carrying our mark that the build no longer ships are removed, so a rename cannot leave
 *   the superseded copy behind, still applying its old rules.
 * - Anything without our mark and without a matching name is never touched.
 * - Deleting one of these styles by hand sticks until the library next changes, since the hash
 *   still matches and the sync does not run.
 *
 * The read of `styleMap` has to happen after initStyleMap has finished. bgInit runs its jobs under
 * Promise.all, so queueing alongside it would race the database read; bgBusy resolves only once
 * every job is done.
 *
 * @returns {Promise<void>}
 */
export default async function syncDefaultStyles() {
  try {
    if (bgBusy) await bgBusy;
    const hash = hashOf(JSON.stringify(DEFAULT_STYLES));
    if (await prefsDB.get(HASH_KEY) === hash) return;

    /** @type {Map<string, StyleObj>} */
    const byName = new Map();
    for (const s of styleMap.values()) byName.set(s.name, s);

    const shippedNames = new Set(DEFAULT_STYLES.map(s => s.name));
    const items = [];
    let adopted = 0;
    for (const src of DEFAULT_STYLES) {
      // importMany() mutates what it is given — fixKnownProblems adds _id/_rev in place — and the
      // imported JSON is a live module object, so it must not be handed over directly.
      const item = deepCopy(src);
      item[MARK] = 1;
      const old = byName.get(src.name);
      if (old) {
        item.id = old.id;
        if (old._id) item._id = old._id;
        item.enabled = old.enabled;
        if (old.exclusions?.length) item.exclusions = old.exclusions;
        if (old.inclusions?.length) item.inclusions = old.inclusions;
        // `overridden` is the "only apply to included sites" switch. Once a profile has an opinion
        // about it, keep that opinion — otherwise every library update would re-tick a box the
        // user deliberately cleared.
        if ('overridden' in old) item.overridden = old.overridden;
        if (old.customName) item.customName = old.customName;
        if (!old[MARK]) adopted++;
      }
      items.push(item);
    }
    const res = await importMany(items);
    const errors = res.filter(r => r.err);

    let removed = 0;
    for (const s of [...styleMap.values()]) {
      if (s[MARK] && !shippedNames.has(s.name)) {
        await remove(s.id);
        removed++;
      }
    }

    await prefsDB.put(hash, HASH_KEY);
    console.log(`default styles synced: ${res.length - errors.length}/${res.length} written` +
      (adopted ? `, ${adopted} adopted by name` : '') +
      (removed ? `, ${removed} withdrawn` : ''));
    if (errors.length) console.warn('default styles rejected:', errors);
  } catch (err) {
    // Never let this take the startup down with it: a stale library is a recoverable state,
    // a background page that died on the way up is not.
    console.error('default styles could not be synced:', err);
  }
}

bgBusy.then(syncDefaultStyles);
